#!/usr/bin/env bash
# Setup-convex.sh generates the KalaNidhi self-hosted Convex state.
#
# Usage:
#   bash deploy/setup-convex.sh          # pre-start: env files under data/kalanidhi
#   bash deploy/setup-convex.sh --post   # post-start: fetch + store the admin key
#
# Installs (never committed; all mode 600):
#   data/kalanidhi/convex.env             backend env + INSTANCE_SECRET
#   data/kalanidhi/convex-functions.env   BETTER_AUTH_SECRET + PAYMENTS_INTERNAL_KEY
#   data/kalanidhi/convex-admin-key       generated by the backend (--post)
#
# Existing files are kept, so re-running never rotates a secret. Secrets are
# never printed: read them from the 600 files on the box.
set -euo pipefail

source "$(cd "$(dirname "$0")" && pwd)/lib.sh"

KALANIDHI_DATA="$DATA_DIR/kalanidhi"
ENV_SRC="$REPO_DIR/services/env/convex.env.example"
ENV_OUT="$KALANIDHI_DATA/convex.env"
FUNCTIONS_SRC="$REPO_DIR/services/env/convex-functions.env.example"
FUNCTIONS_OUT="$KALANIDHI_DATA/convex-functions.env"
APP_ENV="$KALANIDHI_DATA/.env"
ADMIN_KEY="$KALANIDHI_DATA/convex-admin-key"
CONVEX_CONTAINER="${CONVEX_CONTAINER:-services-convex-1}"
CLOUD_URL="https://convex.kalanidhi.site"

usage() {
	cat <<'EOF'
Setup-convex.sh generates the KalaNidhi self-hosted Convex state.

Usage:
  bash deploy/setup-convex.sh          # pre-start: env files under data/kalanidhi
  bash deploy/setup-convex.sh --post   # post-start: fetch + store the admin key

Existing secrets are kept. To regenerate one, remove its file and run again.
EOF
}

# Print the operator commands AFTER the backend exists. The admin key and the
# function secrets stay in files, so nothing sensitive lands in shell history
# or logs.
post() {
	if [ -s "$ADMIN_KEY" ]; then
		keep_existing "$ADMIN_KEY"
	else
		if ! run_as_podman podman inspect "$CONVEX_CONTAINER" >/dev/null 2>&1; then
			die "$CONVEX_CONTAINER is not running; start convex and retry"
		fi
		output="$(run_as_podman podman exec "$CONVEX_CONTAINER" ./generate_admin_key.sh 2>/dev/null || true)"
		key="$(printf '%s\n' "$output" | tr -d '\r' | grep '|' | tail -n 1 || true)"
		[ -n "$key" ] || die "could not generate the Convex admin key from $CONVEX_CONTAINER"
		tmp="$(mktemp)"
		printf '%s\n' "$key" >"$tmp"
		install_file "$tmp" "$ADMIN_KEY" 600
		rm -f "$tmp"
		echo "wrote $ADMIN_KEY (600, credentials; never commit)"
	fi

	cat <<EOF
Convex is reachable at $CLOUD_URL
Dashboard: https://convex-admin.kalanidhi.site (Traefik basic auth, then the
admin key from $ADMIN_KEY).

From the KalaNidhi app repo (the one holding convex/):

  export CONVEX_SELF_HOSTED_URL=$CLOUD_URL
  export CONVEX_SELF_HOSTED_ADMIN_KEY="\$(cat $ADMIN_KEY)"
  npx convex env set BETTER_AUTH_SECRET "\$(sed -n 's/^BETTER_AUTH_SECRET=//p' $FUNCTIONS_OUT)"
  npx convex env set SITE_URL https://kalanidhi.site
  npx convex env set PAYMENTS_INTERNAL_KEY "\$(sed -n 's/^PAYMENTS_INTERNAL_KEY=//p' $FUNCTIONS_OUT)"
  npx convex deploy

Function secrets live only in $FUNCTIONS_OUT (600); the commands read
them at run time so they are not echoed here.
EOF
}

case "${1:-}" in
--post)
	post
	exit 0
	;;
-h | --help)
	usage
	exit 0
	;;
"") ;;
*)
	die "unknown option: $1 (see --help)"
	;;
esac

need_cmd openssl

# 1. Backend env. INSTANCE_SECRET is the only secret; origins and flags are
#    static and rendered from the committed template.
if [ -e "$ENV_OUT" ]; then
	keep_existing "$ENV_OUT"
else
	[ -f "$ENV_SRC" ] || die "missing template: $ENV_SRC"
	instance_secret="${INSTANCE_SECRET:-$(new_hex 32)}"
	tmp="$(mktemp)"
	trap 'rm -f "$tmp"' EXIT
	sed -e "s|{{CONVEX_INSTANCE_SECRET}}|$instance_secret|g" "$ENV_SRC" >"$tmp"
	grep -q '{{' "$tmp" && die "unrendered placeholder in $ENV_SRC"
	install_file "$tmp" "$ENV_OUT" 600
	trap - EXIT
	rm -f "$tmp"
	echo "wrote $ENV_OUT (600, contains INSTANCE_SECRET; never commit)"
fi

# 2. Convex deployment env for the app's functions. Set through the CLI, not
#    read by the backend container.
if [ -e "$FUNCTIONS_OUT" ]; then
	keep_existing "$FUNCTIONS_OUT"
else
	[ -f "$FUNCTIONS_SRC" ] || die "missing template: $FUNCTIONS_SRC"
	better_auth_secret="${BETTER_AUTH_SECRET:-$(new_hex 32)}"
	payments_key="${PAYMENTS_INTERNAL_KEY:-$(new_hex 32)}"
	tmp="$(mktemp)"
	trap 'rm -f "$tmp"' EXIT
	sed -e "s|{{BETTER_AUTH_SECRET}}|$better_auth_secret|g" \
		-e "s|{{PAYMENTS_INTERNAL_KEY}}|$payments_key|g" "$FUNCTIONS_SRC" >"$tmp"
	grep -q '{{' "$tmp" && die "unrendered placeholder in $FUNCTIONS_SRC"
	install_file "$tmp" "$FUNCTIONS_OUT" 600
	trap - EXIT
	rm -f "$tmp"
	echo "wrote $FUNCTIONS_OUT (600, credentials; never commit)"
fi

# 3. App env: non-secret public URLs only. Created once, then only missing or
#    empty keys are filled in (an operator's edits are never overwritten).
if [ ! -e "$APP_ENV" ]; then
	tmp="$(mktemp)"
	trap 'rm -f "$tmp"' EXIT
	cat >"$tmp" <<EOF
# KalaNidhi runtime environment. Generated by deploy/setup-convex.sh; edit
# values here, never in the repo. LiveKit credentials arrive from livekit.env.
CONVEX_URL=$CLOUD_URL
NEXT_PUBLIC_CONVEX_URL=$CLOUD_URL
CONVEX_SITE_URL=https://convex-site.kalanidhi.site
NEXT_PUBLIC_CONVEX_SITE_URL=https://convex-site.kalanidhi.site
NEXT_PUBLIC_SITE_URL=https://kalanidhi.site
LIVEKIT_PUBLIC_URL=wss://livekit.kalanidhi.site
EOF
	install_file "$tmp" "$APP_ENV" 600
	trap - EXIT
	rm -f "$tmp"
	echo "wrote $APP_ENV (600)"
else
	env_ensure "$APP_ENV" CONVEX_URL "$CLOUD_URL"
	env_ensure "$APP_ENV" NEXT_PUBLIC_CONVEX_URL "$CLOUD_URL"
	env_ensure "$APP_ENV" CONVEX_SITE_URL "https://convex-site.kalanidhi.site"
	env_ensure "$APP_ENV" NEXT_PUBLIC_CONVEX_SITE_URL "https://convex-site.kalanidhi.site"
	env_ensure "$APP_ENV" NEXT_PUBLIC_SITE_URL "https://kalanidhi.site"
	env_ensure "$APP_ENV" LIVEKIT_PUBLIC_URL "wss://livekit.kalanidhi.site"
fi

echo
echo "next: start the services, then run: bash deploy/setup-convex.sh --post"
